BEGIN; CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS analyst_tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active',password_hash text);
ALTER TABLE analyst_users ADD COLUMN IF NOT EXISTS password_hash text;
CREATE TABLE IF NOT EXISTS analyst_memberships(tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),user_id uuid NOT NULL REFERENCES analyst_users(id),role text NOT NULL,groups jsonb NOT NULL DEFAULT '[]'::jsonb,permissions jsonb NOT NULL DEFAULT '[]'::jsonb,status text NOT NULL DEFAULT 'active',PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS analyst_connectors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),kind text NOT NULL,repository text NOT NULL,scopes jsonb NOT NULL,credential_reference text NOT NULL,status text NOT NULL CHECK(status IN('active','paused','revoked','deletion_pending')),created_by uuid NOT NULL REFERENCES analyst_users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,repository));
CREATE TABLE IF NOT EXISTS analyst_connector_checkpoints(tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),connector_id uuid NOT NULL REFERENCES analyst_connectors(id),cursor text,page_digest text,lease_token uuid,lease_expires_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,connector_id));
CREATE TABLE IF NOT EXISTS analyst_sources(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),connector_id uuid REFERENCES analyst_connectors(id),repository text NOT NULL,external_id text NOT NULL,version text NOT NULL,sha256 text NOT NULL,authority text NOT NULL,observed_at timestamptz NOT NULL,allowed_subjects jsonb NOT NULL,retention_policy jsonb NOT NULL,object_key text NOT NULL,provenance_digest text NOT NULL,status text NOT NULL CHECK(status IN('ingested','parsing','indexed','quarantined','deletion_pending','deleted')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,repository,external_id,version),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS analyst_chunks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),source_id uuid NOT NULL REFERENCES analyst_sources(id),source_version text NOT NULL,ordinal integer NOT NULL,text_content text NOT NULL,location jsonb NOT NULL,parser_version text NOT NULL,allowed_subjects jsonb NOT NULL,injection_signals jsonb NOT NULL,chunk_digest text NOT NULL,status text NOT NULL CHECK(status IN('ready','quarantined','deleted')),UNIQUE(source_id,ordinal));
CREATE TABLE IF NOT EXISTS analyst_index_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),source_id uuid NOT NULL REFERENCES analyst_sources(id),index_version text NOT NULL,idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN('pending','claimed','indexed','retry','dead_letter','cancelled')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 5),lease_token uuid,lease_expires_at timestamptz,next_attempt_at timestamptz,last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS analyst_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),user_id uuid NOT NULL REFERENCES analyst_users(id),question text NOT NULL,permission_snapshot jsonb NOT NULL,retrieval_version text NOT NULL,model_version text NOT NULL,cost_limit_minor bigint NOT NULL,status text NOT NULL CHECK(status IN('queued','answered','abstained','failed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),question_id uuid NOT NULL REFERENCES analyst_questions(id),status text NOT NULL CHECK(status IN('answered','abstained')),answer text,reason text,citations jsonb NOT NULL,limitations jsonb NOT NULL,answer_digest text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),dataset_version text NOT NULL,policy_version text NOT NULL,passed boolean NOT NULL,failures jsonb NOT NULL,metrics jsonb NOT NULL,created_by uuid NOT NULL REFERENCES analyst_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_visualization_specs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),dataset_version_id text NOT NULL,dataset_digest text NOT NULL,schema_version text NOT NULL,library text NOT NULL CHECK(library IN('plotly','d3','deck.gl')),spec jsonb NOT NULL,spec_digest text NOT NULL,status text NOT NULL CHECK(status IN('draft','approved','queued','rendered','failed','cancelled')),created_by uuid NOT NULL REFERENCES analyst_users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS analyst_visualization_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),spec_id uuid NOT NULL REFERENCES analyst_visualization_specs(id),reviewer_id uuid NOT NULL REFERENCES analyst_users(id),spec_digest text NOT NULL,decision text NOT NULL CHECK(decision IN('approved','rejected')),query_plan_digest text NOT NULL,cost_limit_minor bigint NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(spec_id,reviewer_id));
CREATE TABLE IF NOT EXISTS analyst_provider_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),capability text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,command jsonb NOT NULL,payload_digest text NOT NULL,idempotency_key text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','claimed','delivered','retry','dead_letter','cancelled')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 5),lease_token uuid,lease_expires_at timestamptz,next_attempt_at timestamptz,last_error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,capability,idempotency_key));
CREATE TABLE IF NOT EXISTS analyst_provider_receipts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),outbox_id bigint REFERENCES analyst_provider_outbox(id),provider text NOT NULL,receipt_id text NOT NULL,status text NOT NULL,payload_digest text NOT NULL,usage jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL,UNIQUE(provider,receipt_id));
CREATE TABLE IF NOT EXISTS analyst_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),answer_id uuid REFERENCES analyst_answers(id),spec_id uuid REFERENCES analyst_visualization_specs(id),user_id uuid NOT NULL REFERENCES analyst_users(id),disposition text NOT NULL,correction jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_legal_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),source_id uuid NOT NULL REFERENCES analyst_sources(id),reason text NOT NULL,status text NOT NULL CHECK(status IN('active','released')),placed_by uuid NOT NULL REFERENCES analyst_users(id),placed_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz);
CREATE TABLE IF NOT EXISTS analyst_deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),source_id uuid NOT NULL REFERENCES analyst_sources(id),status text NOT NULL CHECK(status IN('requested','propagating','blocked_by_hold','completed','failed')),legal_hold boolean NOT NULL DEFAULT false,plan jsonb NOT NULL,requested_by uuid NOT NULL REFERENCES analyst_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyst_deletion_propagations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),request_id uuid NOT NULL REFERENCES analyst_deletion_requests(id),target text NOT NULL,status text NOT NULL CHECK(status IN('pending','sent','confirmed','failed')),receipt_id text,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,target));
CREATE TABLE IF NOT EXISTS analyst_audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES analyst_tenants(id),actor_id uuid REFERENCES analyst_users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION analyst_reject_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'analyst evidence is append-only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['analyst_chunks','analyst_answers','analyst_evaluations','analyst_visualization_approvals','analyst_provider_receipts','analyst_feedback','analyst_audit_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS immutable_evidence ON %I',t);EXECUTE format('CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION analyst_reject_evidence_mutation()',t);END LOOP;FOREACH t IN ARRAY ARRAY['analyst_memberships','analyst_connectors','analyst_connector_checkpoints','analyst_sources','analyst_chunks','analyst_index_jobs','analyst_questions','analyst_answers','analyst_evaluations','analyst_visualization_specs','analyst_visualization_approvals','analyst_provider_outbox','analyst_provider_receipts','analyst_feedback','analyst_legal_holds','analyst_deletion_requests','analyst_deletion_propagations','analyst_audit_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);END LOOP;END $$;
COMMIT;
